pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testFuzz_property(address from, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(v <= type(uint256).max / _tos.length);

        Reverter reverter = new Reverter();
        address caddress = address(reverter);

        bool ok;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
